package com.hibernate.ecommerce.mapper;import com.hibernate.ecommerce.dto.OrderdetailsDTO;import com.hibernate.ecommerce.model.Order;import com.hibernate.ecommerce.model.Orderdetails;import com.hibernate.ecommerce.model.Product;public class OrderdetailsMapper {    public static OrderdetailsDTO toDTO(Orderdetails orderdetails){        if( orderdetails == null) return null;        return OrderdetailsDTO.builder()                .id(orderdetails.getId())                .orderId(orderdetails.getOrder().getId())                .productId(orderdetails.getProduct().getId())                .price(orderdetails.getPrice())                .quantity(orderdetails.getQuantity())                .build();    }    public static Orderdetails toEntity(OrderdetailsDTO dto, Order order, Product product){        if(dto == null) return null;        return Orderdetails.builder()                .id(dto.getId())                .product(product)                .quantity(dto.getQuantity())                .price(dto.getPrice())                .order(order)                .build();    }}